import math

def probability_at_least_two(n):
    if n > 365:
        return 1.0
    prob_no_shared = 1.0
    for i in range(n - 1):
        prob_no_shared *= (365 - i) / 365
    return 1 - prob_no_shared

def probability_at_least_three(n):
    if n > 365:
        return 1.0
    prob_no_shared = 1.0
    for i in range(n):
        prob_no_shared *= (365 - i) / 365
    prob_no_triple = 1.0
    for i in range(n):
        prob_no_triple *= (365 - i) / 365
    return 1 - prob_no_triple
